 <div class="mobile-controls"><button class="touch-btn" id="jumpBtn" aria-label="Jump">↑</button><button class="touch-btn" id="slideBtn" aria-label="Slide">↓</button></div>
 <div class="center-panel" id="panel"><div class="card"><div class="eyebrow" id="eyebrow">🌧&nbsp; DHAKA, BANGLADESH</div><h1 id="title">MONSOON<br><span>DASH</span></h1><p id="message">The rain's let up and the streets are calling. Dash through Old Dhaka, scoop up mangoes, and dodge whatever the monsoon left behind.</p><div class="feature-row" id="features"><span>🥭 Collect mangoes</span><span>↗ Jump &amp; slide</span></div><button class="main-btn" id="startBtn">START YOUR RUN&nbsp; →</button><p class="hint" id="hint">SPACE / ↑ to jump&nbsp; · &nbsp;↓ to slide&nbsp; · &nbsp;P to pause</p></div></div>
 </section></main>
 <script>
+(()=>{
+const canvas=document.getElementById('game'),ctx=canvas.getContext('2d');
+const $=id=>document.getElementById(id);
+const ui={panel:$('panel'),title:$('title'),message:$('message'),eyebrow:$('eyebrow'),features:$('features'),start:$('startBtn'),hint:$('hint'),mango:$('mangoCount'),distance:$('distance'),progress:$('progress'),pause:$('pauseBtn'),sound:$('soundBtn'),controlsHint:$('controlsHint')};
+let W=960,H=540,ground=430,state='ready',score=0,meters=0,speed=330,elapsed=0,spawnTimer=1.2,last=0,muted=true,audioCtx=null;
+let obstacles=[],mangoes=[],particles=[],rain=[],skyline=[],buildings=[],player={x:170,y:0,vy:0,w:40,h:56,grounded:true,sliding:false,slideT:0,anim:0,invuln:0};
+const rand=(a,b)=>a+Math.random()*(b-a),clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
+function resize(){const r=canvas.getBoundingClientRect();const ratio=r.width? r.height/r.width:9/16;W=960;H=Math.max(540,960*ratio);canvas.width=W;canvas.height=H;ground=H-Math.min(128,Math.max(104,H*.2));player.y=ground-player.h;}
+new ResizeObserver(resize).observe(canvas);resize();
+function makeScenery(){skyline=[];for(let x=0;x<1300;x+=rand(65,145))skyline.push({x,w:rand(48,105),h:rand(110,245),tone:Math.floor(rand(0,4)),roof:Math.floor(rand(0,4))});buildings=[];for(let x=0;x<1500;x+=rand(105,185))buildings.push({x,w:rand(90,155),h:rand(110,195),color:['#e9b879','#e67f59','#ddc18d','#bda879','#f0a166'][Math.floor(rand(0,5))],awning:Math.random()>.35});}
+makeScenery();
+function rounded(x,y,w,h,r,fill){ctx.fillStyle=fill;ctx.beginPath();ctx.roundRect(x,y,w,h,r);ctx.fill();}
+function sound(freq=540,duration=.08,type='sine'){if(muted)return;try{audioCtx??=new(window.AudioContext||window.webkitAudioContext)();const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type=type;o.frequency.value=freq;g.gain.setValueAtTime(.055,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+duration);o.connect(g);g.connect(audioCtx.destination);o.start();o.stop(audioCtx.currentTime+duration)}catch{}}
+function showPanel(mode){ui.panel.classList.remove('hidden');if(mode==='ready'){ui.eyebrow.innerHTML='🌧&nbsp; DHAKA, BANGLADESH';ui.title.innerHTML='MONSOON<br><span>DASH</span>';ui.message.textContent="The rain's let up and the streets are calling. Dash through Old Dhaka, scoop up mangoes, and dodge whatever the monsoon left behind.";ui.features.innerHTML='<span>🥭 Collect mangoes</span><span>↗ Jump &amp; slide</span>';ui.start.innerHTML='START YOUR RUN&nbsp; →';ui.hint.style.display='';ui.start.onclick=startGame}else if(mode==='over'){ui.eyebrow.innerHTML='🏁&nbsp; RUN COMPLETE';ui.title.innerHTML='NICE<br><span>RUN!</span>';ui.message.textContent='The streets of Dhaka never slow down for long. Ready for another lap?';ui.features.innerHTML=`<span>🥭 ${score} mango${score===1?'':'es'}</span><span>📍 ${Math.floor(meters)}m travelled</span>`;ui.start.innerHTML='RUN IT BACK&nbsp; ↻';ui.hint.textContent='Tip: slide under the hanging laundry';ui.hint.style.display='';ui.start.onclick=startGame}else if(mode==='paused'){ui.eyebrow.innerHTML='⏸&nbsp; CATCH YOUR BREATH';ui.title.innerHTML='PAUSE<br><span>BREAK</span>';ui.message.textContent='Even a rickshaw-wallah needs a breather. Your run is right where you left it.';ui.features.innerHTML=`<span>🥭 ${score} mangoes</span><span>📍 ${Math.floor(meters)}m</span>`;ui.start.innerHTML='BACK TO THE RUN&nbsp; →';ui.hint.style.display='none';ui.start.onclick=()=>{state='running';ui.panel.classList.add('hidden');last=performance.now()}}}
+function startGame(){state='running';score=0;meters=0;speed=330;elapsed=0;spawnTimer=.8;obstacles=[];mangoes=[];particles=[];player.y=ground-player.h;player.vy=0;player.grounded=true;player.sliding=false;ui.mango.textContent='0';ui.distance.textContent='0m';ui.progress.style.width='0%';ui.panel.classList.add('hidden');last=performance.now();sound(620,.12)}
+function endGame(){if(state!=='running')return;state='over';sound(145,.28,'sawtooth');for(let i=0;i<16;i++)particles.push({x:player.x+20,y:player.y+20,vx:rand(-190,190),vy:rand(-240,70),life:rand(.4,.9),color:'#f5aa46',size:rand(3,7)});showPanel('over')}
+function pause(){if(state==='running'){state='paused';showPanel('paused')}else if(state==='paused'){state='running';ui.panel.classList.add('hidden');last=performance.now()}}
+function jump(){if(state!=='running')return;if(player.grounded){player.vy=-680;player.grounded=false;player.sliding=false;sound(430,.08)}}
+function slide(on=true){if(state!=='running')return;if(on&&player.grounded){player.sliding=true;player.slideT=.55}else if(!on)player.sliding=false}
+function addMango(x,y){mangoes.push({x,y,r:13,phase:rand(0,6.28),got:false})}
+function spawn(){const x=W+65,kind=Math.random();if(kind<.55){const type=Math.random()<.54?'puddle':'crate';obstacles.push({x,y:ground-(type==='crate'?38:17),w:type==='crate'?37:61,h:type==='crate'?38:17,type})}else if(kind<.79){obstacles.push({x,y:ground-82,w:82,h:22,type:'laundry',phase:rand(0,6)})}else{obstacles.push({x,y:ground-42,w:52,h:42,type:'rickshaw',phase:0})}
+if(Math.random()<.82){const n=Math.random()<.35?4:3;for(let i=0;i<n;i++)addMango(x+70+i*38,ground-rand(95,150)+(i%2)*18)} }
+function addRain(){for(let i=0;i<65;i++)rain.push({x:rand(0,W),y:rand(-H,H),l:rand(8,19),v:rand(390,720)})}addRain();

