function addRain(){for(let i=0;i<65;i++)rain.push({x:rand(0,W),y:rand(-H,H),l:rand(8,19),v:rand(390,720)})}addRain();
function drawCloud(x,y,s){ctx.save();ctx.translate(x,y);ctx.scale(s,s);ctx.fillStyle='#f6fff0a8';ctx.beginPath();ctx.arc(0,7,18,0,Math.PI*2);ctx.arc(20,0,24,0,Math.PI*2);ctx.arc(44,8,17,0,Math.PI*2);ctx.rect(0,7,44,18);ctx.fill();ctx.restore()}
function drawBackdrop(dt){
const sky=ctx.createLinearGradient(0,0,0,H);sky.addColorStop(0,'#83cfc3');sky.addColorStop(.52,'#b5e3c9');sky.addColorStop(1,'#e5e9b8');ctx.fillStyle=sky;ctx.fillRect(0,0,W,H);
// sun and soft monsoon clouds
ctx.fillStyle='#fff0b0';ctx.beginPath();ctx.arc(785,Math.max(92,ground-280),35,0,Math.PI*2);ctx.fill();
drawCloud(90,Math.max(80,ground-300),.8);drawCloud(455,Math.max(130,ground-250),.66);drawCloud(840,Math.max(65,ground-375),.7);
// distant Dhaka skyline
const travel=meters*.22%1300;
for(const b of skyline){let x=(b.x-travel+1300)%1300-50,y=ground-55-b.h;ctx.fillStyle=['#7bb7a5','#73a999','#64988b','#85b6a1'][b.tone];ctx.fillRect(x,y,b.w,b.h);ctx.fillStyle='#67978a';ctx.fillRect(x-5,y+8,b.w+10,7);if(b.roof===1){ctx.fillRect(x+b.w*.35,y-13,b.w*.3,13);ctx.fillRect(x+b.w*.46,y-27,4,14)}if(b.roof===2){ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x+b.w/2,y-19);ctx.lineTo(x+b.w,y);ctx.fill()}for(let wy=y+18;wy<ground-65;wy+=25)for(let wx=x+10;wx<x+b.w-5;wx+=18){ctx.fillStyle='#e7d89a99';ctx.fillRect(wx,wy,6,9)}}
// distant tree line
for(let i=0;i<8;i++){const x=((i*181-meters*.38%1448+1448)%1448)-40,cy=ground-49;ctx.fillStyle='#357e66';ctx.fillRect(x+17,cy-66,9,65);ctx.fillStyle=i%2?'#378f6d':'#448f68';ctx.beginPath();ctx.arc(x+19,cy-75,31,0,Math.PI*2);ctx.arc(x+1,cy-57,21,0,Math.PI*2);ctx.arc(x+39,cy-55,20,0,Math.PI*2);ctx.fill()}
// near colorful Old Dhaka shopfronts
for(const b of buildings){let x=(b.x-meters*.65%1500+1500)%1500-100,y=ground-64-b.h;ctx.fillStyle=b.color;ctx.fillRect(x,y,b.w,b.h);ctx.fillStyle='#83594a55';ctx.fillRect(x,y,b.w,8);ctx.fillStyle='#f3d9a7';ctx.fillRect(x+9,y+13,b.w-18,22);ctx.fillStyle=['#167457','#b94335','#d18a30'][Math.floor(b.x/130)%3];ctx.fillRect(x+9,y+13,b.w-18,3);ctx.fillStyle='#3d6c61';for(let wx=x+12;wx<x+b.w-13;wx+=24){ctx.fillRect(wx,y+47,14,26);ctx.fillStyle='#b9ded0';ctx.fillRect(wx+3,y+50,8,16);ctx.fillStyle='#3d6c61'}if(b.awning){ctx.fillStyle='#f2bd52';ctx.fillRect(x-5,y+82,b.w+10,8);for(let wx=x-5;wx<x+b.w;wx+=16){ctx.fillStyle='#cf583f';ctx.beginPath();ctx.moveTo(wx,y+90);ctx.lineTo(wx+8,y+90);ctx.lineTo(wx+4,y+99);ctx.fill()}}ctx.fillStyle='#604d3b';ctx.fillRect(x+12,ground-91,22,27);ctx.fillStyle='#2c7761';ctx.fillRect(x+12,ground-87,22,4)}
// Bangladesh flag on a roadside pole
const flagX=(710-meters*.48%1100+1100)%1100;ctx.fillStyle='#527b5f';ctx.fillRect(flagX,ground-175,3,111);ctx.fillStyle='#08794d';ctx.fillRect(flagX+3,ground-170,51,30);ctx.fillStyle='#e33e37';ctx.beginPath();ctx.arc(flagX+25,ground-155,8,0,Math.PI*2);ctx.fill();
// sidewalk and street
ctx.fillStyle='#d5bd8c';ctx.fillRect(0,ground-30,W,30);ctx.fillStyle='#f5dfac';ctx.fillRect(0,ground-31,W,5);ctx.fillStyle='#b8956a';for(let x=-(meters*1.1%75);x<W;x+=75){ctx.fillRect(x,ground-24,2,18)}
ctx.fillStyle='#657f69';ctx.fillRect(0,ground,W,H-ground);ctx.fillStyle='#4f6658';ctx.fillRect(0,ground+7,W,H-ground-7);
// road dash marks
ctx.fillStyle='#e4d7a366';for(let x=-(meters*1.8%140);x<W;x+=140)ctx.fillRect(x,ground+73,62,4);
// rain slashes and puddle glints
if(state==='running'||state==='ready'){ctx.strokeStyle='#e9ffff40';ctx.lineWidth=1.5;for(const r of rain){ctx.beginPath();ctx.moveTo(r.x,r.y);ctx.lineTo(r.x-5,r.y+r.l);ctx.stroke()}}
}
function drawMango(m){const bob=Math.sin(elapsed*5+m.phase)*4;ctx.save();ctx.translate(m.x,m.y+bob);ctx.rotate(Math.sin(elapsed*2+m.phase)*.12);ctx.fillStyle='#f2ae3d';ctx.beginPath();ctx.ellipse(0,0,11,14,.3,0,Math.PI*2);ctx.fill();ctx.fillStyle='#e9812f';ctx.beginPath();ctx.ellipse(4,3,5,8,.35,0,Math.PI*2);ctx.fill();ctx.fillStyle='#337e4d';ctx.beginPath();ctx.ellipse(6,-14,6,3,-.4,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#2e6943';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(1,-11);ctx.lineTo(3,-15);ctx.stroke();ctx.restore()}
function drawObstacle(o){ctx.save();if(o.type==='puddle'){ctx.fillStyle='#478f91';ctx.beginPath();ctx.ellipse(o.x+o.w/2,o.y+o.h/2,o.w/2,o.h/2,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#bde8d1';ctx.beginPath();ctx.ellipse(o.x+o.w*.34,o.y+4,10,2,0,0,Math.PI*2);ctx.fill()}else if(o.type==='crate'){rounded(o.x,o.y,o.w,o.h,4,'#a95737');ctx.fillStyle='#d09149';ctx.fillRect(o.x+4,o.y+5,o.w-8,5);ctx.strokeStyle='#80432f';ctx.lineWidth=3;ctx.strokeRect(o.x+5,o.y+11,o.w-10,o.h-15);ctx.beginPath();ctx.moveTo(o.x+8,o.y+12);ctx.lineTo(o.x+o.w-8,o.y+o.h-4);ctx.moveTo(o.x+o.w-8,o.y+12);ctx.lineTo(o.x+8,o.y+o.h-4);ctx.stroke()}else if(o.type==='laundry'){ctx.fillStyle='#806b4e';ctx.fillRect(o.x+3,o.y-8,o.w-6,5);ctx.strokeStyle='#e7efe0';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(o.x,o.y-4);ctx.lineTo(o.x+o.w,o.y-4);ctx.stroke();for(let i=0;i<4;i++){const w=17,x=o.x+5+i*19,drop=Math.sin(elapsed*5+o.phase+i)*2;ctx.fillStyle=['#db5547','#f2c65a','#76b9a2','#f4e3b5'][i];ctx.beginPath();ctx.moveTo(x,o.y-4);ctx.lineTo(x+w,o.y-4);ctx.lineTo(x+w-2,o.y+18+drop);ctx.lineTo(x+2,o.y+18);ctx.fill()}}else if(o.type==='rickshaw'){// parked hand-pulled rickshaw
ctx.strokeStyle='#295c4e';ctx.lineWidth=4;ctx.beginPath();ctx.arc(o.x+13,o.y+o.h-4,9,0,Math.PI*2);ctx.arc(o.x+44,o.y+o.h-4,9,0,Math.PI*2);ctx.stroke();ctx.strokeStyle='#d34739';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(o.x+13,o.y+o.h-4);ctx.lineTo(o.x+24,o.y+12);ctx.lineTo(o.x+44,o.y+o.h-4);ctx.moveTo(o.x+20,o.y+15);ctx.lineTo(o.x+50,o.y+18);ctx.stroke();ctx.fillStyle='#e8543e';ctx.beginPath();ctx.moveTo(o.x+13,o.y+12);ctx.quadraticCurveTo(o.x+28,o.y-10,o.x+49,o.y+13);ctx.lineTo(o.x+13,o.y+16);ctx.fill();ctx.fillStyle='#f6c756';ctx.fillRect(o.x+21,o.y+11,3,9);ctx.fillRect(o.x+33,o.y+8,3,12)}ctx.restore()}

